CREATE TABLE format_states(team_id TEXT PRIMARY KEY REFERENCES teams(id),revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE format_rules(team_id TEXT NOT NULL REFERENCES teams(id),id TEXT NOT NULL,selector TEXT NOT NULL,rows_json TEXT,keys_json TEXT,exclusions_json TEXT NOT NULL,style_id INTEGER NOT NULL REFERENCES styles(id),orders_json TEXT NOT NULL,PRIMARY KEY(team_id,id),UNIQUE(team_id,selector));
CREATE TABLE views(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),team_id TEXT NOT NULL REFERENCES teams(id),year INTEGER NOT NULL,name TEXT NOT NULL,data TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(user_id,team_id,year,name));
CREATE TABLE saved_filters(id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams(id),scope TEXT NOT NULL CHECK(scope IN ('team','personal')),owner_id TEXT REFERENCES users(id),name TEXT NOT NULL,data TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK((scope='team' AND owner_id IS NULL) OR (scope='personal' AND owner_id IS NOT NULL)));
CREATE TABLE filter_states(user_id TEXT NOT NULL REFERENCES users(id),team_id TEXT NOT NULL REFERENCES teams(id),selected_id TEXT REFERENCES saved_filters(id) ON DELETE SET NULL,data TEXT NOT NULL,PRIMARY KEY(user_id,team_id));
CREATE TABLE reports(id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams(id),year INTEGER NOT NULL,name TEXT NOT NULL,reference_date TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,data BLOB NOT NULL CHECK(typeof(data)='blob'));
