CREATE TABLE calendar_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,weekdays TEXT NOT NULL);
CREATE TABLE calendar_rules(team_id TEXT PRIMARY KEY REFERENCES teams(id) ON DELETE CASCADE,property_id TEXT NOT NULL,filter_values TEXT NOT NULL,filter_mode TEXT NOT NULL DEFAULT 'include' CHECK(filter_mode IN ('include','exclude')),revision INTEGER NOT NULL);
CREATE TABLE calendar_entries(id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id),date TEXT NOT NULL,end_date TEXT NOT NULL CHECK(end_date>=date),lane INTEGER NOT NULL DEFAULT 0 CHECK(lane>=0),title TEXT NOT NULL,preview TEXT NOT NULL DEFAULT '',version_id TEXT REFERENCES document_versions(id),revision INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),operation_id TEXT,request_hash TEXT,deleted_at TEXT,deletion_id TEXT);
INSERT INTO calendar_entries VALUES('b10727a3-443f-465d-a7ef-e1e833dc451a','377e8e56-aea7-46ea-a51e-0715b9b79ca3','7ba14b00-2d4f-4b4a-8397-4d17aa3df01e','2026-10-07','2026-10-07',0,'일정 문서','일정 본문 사본 메모 와 업무','d2844d5f-1fc5-4250-b55a-c4d7b4ff0272',1,'2026-11-07T16:37:15.346Z','7ba14b00-2d4f-4b4a-8397-4d17aa3df01e','8b0d7a27-1f8d-4f40-b1e6-ed1e6c4ccfba','de2a5fcd1f2b8debb63623c8416435409ce5d6e16bedec9f27bc9c688480d609',NULL,NULL);
CREATE TABLE calendar_tags(id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id),name TEXT NOT NULL COLLATE NOCASE,color TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'label' CHECK(kind IN ('label','check')),revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE calendar_entry_tags(entry_id TEXT NOT NULL REFERENCES calendar_entries(id) ON DELETE CASCADE,tag_id TEXT NOT NULL REFERENCES calendar_tags(id) ON DELETE CASCADE,position INTEGER NOT NULL,checked INTEGER NOT NULL DEFAULT 0 CHECK(checked IN (0,1)),PRIMARY KEY(entry_id,tag_id),UNIQUE(entry_id,position));
CREATE TABLE calendar_weekly_items(team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),week_start TEXT NOT NULL,task_id TEXT NOT NULL,title TEXT NOT NULL,imported_at TEXT NOT NULL,PRIMARY KEY(team_id,user_id,week_start,task_id));
CREATE TABLE audit(id TEXT PRIMARY KEY,team_id TEXT REFERENCES teams(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,before_json TEXT,after_json TEXT,created_at TEXT NOT NULL);
