CREATE TABLE sync_objects(
 team_id TEXT NOT NULL REFERENCES teams(id), hash TEXT NOT NULL, kind TEXT NOT NULL,
 data BLOB NOT NULL, size INTEGER NOT NULL CHECK(size>=0), PRIMARY KEY(team_id,hash)
);
CREATE TABLE sync_person_refs(
 team_id TEXT NOT NULL REFERENCES teams(id), person_id TEXT NOT NULL, profile TEXT NOT NULL,
 local_user_id TEXT, PRIMARY KEY(team_id,person_id)
);
INSERT INTO sync_person_refs VALUES('377e8e56-aea7-46ea-a51e-0715b9b79ca3','897806d1-39e9-4732-a768-e5f8ac7f7631','{"name":"외부 관리자"}','897806d1-39e9-4732-a768-e5f8ac7f7631');
CREATE TABLE site_retention(
 team_id TEXT NOT NULL REFERENCES teams(id), site_id TEXT NOT NULL, kind TEXT NOT NULL,
 entity_key TEXT NOT NULL, generation TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL,
 created_at TEXT NOT NULL, PRIMARY KEY(team_id,site_id,kind,entity_key,generation)
);
CREATE TABLE site_maintenance_jobs(
 job_id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES teams(id), kind TEXT NOT NULL,
 phase TEXT NOT NULL, manifest TEXT NOT NULL, progress TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE site_entity_revisions(
 team_id TEXT NOT NULL REFERENCES teams(id), entity TEXT NOT NULL, entity_key TEXT NOT NULL,
 revision INTEGER NOT NULL, PRIMARY KEY(team_id,entity,entity_key)
);
CREATE TABLE site_events(
 cursor INTEGER PRIMARY KEY AUTOINCREMENT, team_id TEXT NOT NULL REFERENCES teams(id),
 kind TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE sync_credentials(profile_id TEXT PRIMARY KEY, ciphertext TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE external_setup_keys(
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL,
  issued_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  revoked_at TEXT,
  published_head TEXT,
  published_at TEXT,
  applied_at TEXT,
  used_at TEXT,
  UNIQUE(team_id,user_id)
);
CREATE TABLE access_tokens(
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80),
  token_hash TEXT NOT NULL UNIQUE CHECK(length(token_hash)=64),
  prefix TEXT NOT NULL,
  created_at TEXT NOT NULL,
  token_ciphertext TEXT NOT NULL
);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
INSERT INTO sqlite_sequence VALUES('sync_outbox',1);
CREATE TRIGGER revision_team_insert AFTER INSERT ON teams BEGIN INSERT OR IGNORE INTO team_revisions(team_id) VALUES(NEW.id); END;
CREATE TRIGGER revision_task_insert AFTER INSERT ON tasks BEGIN UPDATE team_revisions SET version=version+1 WHERE team_id=NEW.team_id; END;
CREATE TRIGGER revision_task_update AFTER UPDATE ON tasks BEGIN UPDATE team_revisions SET version=version+1 WHERE team_id=NEW.team_id; END;
CREATE TRIGGER revision_task_delete AFTER DELETE ON tasks BEGIN UPDATE team_revisions SET version=version+1 WHERE team_id=OLD.team_id; END;
CREATE TRIGGER revision_cell_insert AFTER INSERT ON cells BEGIN UPDATE team_revisions SET version=version+1 WHERE team_id=(SELECT team_id FROM tasks WHERE id=NEW.task_id); END;
CREATE TRIGGER revision_cell_update AFTER UPDATE ON cells BEGIN UPDATE team_revisions SET version=version+1 WHERE team_id=(SELECT team_id FROM tasks WHERE id=NEW.task_id); END;
CREATE TRIGGER revision_cell_delete AFTER DELETE ON cells BEGIN UPDATE team_revisions SET version=version+1 WHERE team_id=(SELECT team_id FROM tasks WHERE id=OLD.task_id); END;
CREATE INDEX cells_style_idx ON cells(style_id);
CREATE INDEX tasks_style_idx ON tasks(default_style);
CREATE INDEX tasks_row_style_idx ON tasks(row_style);
CREATE INDEX annual_memos_version_idx ON annual_memos(version_id);
CREATE INDEX task_documents_version_idx ON task_documents(version_id);
CREATE INDEX task_documents_summary_idx ON task_documents(task_id,has_content);
CREATE INDEX format_styles_idx ON format_rules(style_id);
CREATE INDEX tasks_team_idx ON tasks(team_id,deleted_at,position);
CREATE UNIQUE INDEX saved_filters_team_name ON saved_filters(team_id,name) WHERE scope='team';
CREATE UNIQUE INDEX saved_filters_personal_name ON saved_filters(team_id,owner_id,name) WHERE scope='personal';
CREATE INDEX report_documents_version_idx ON report_documents(version_id);
CREATE INDEX report_memos_version_idx ON report_memos(version_id);
CREATE INDEX calendar_entries_scope_idx ON calendar_entries(team_id,date,user_id);
CREATE INDEX calendar_entries_owner_idx ON calendar_entries(team_id,user_id);
CREATE INDEX calendar_entries_layout_start_idx ON calendar_entries(team_id,user_id,date,end_date) WHERE deleted_at IS NULL;
CREATE INDEX calendar_entries_layout_end_idx ON calendar_entries(team_id,user_id,end_date,date) WHERE deleted_at IS NULL;
CREATE INDEX calendar_entries_version_idx ON calendar_entries(version_id);
CREATE UNIQUE INDEX calendar_tags_personal_name_idx ON calendar_tags(team_id,user_id,name) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX calendar_tags_shared_name_idx ON calendar_tags(team_id,name) WHERE user_id IS NULL;
CREATE INDEX calendar_entry_tags_tag_idx ON calendar_entry_tags(tag_id);
CREATE INDEX calendar_weekly_scope_idx ON calendar_weekly_items(team_id,week_start,user_id);
CREATE INDEX audit_team_idx ON audit(team_id,created_at DESC);
CREATE INDEX audit_system_idx ON audit(team_id,created_at DESC,id DESC) WHERE team_id IS NULL;
CREATE INDEX audit_cleanup_team_idx ON audit(team_id,created_at DESC,id DESC) WHERE action='history-cleanup';
CREATE INDEX operations_cell_team_created_idx ON operations((CASE WHEN json_array_length(response,'$.refs')=1 THEN json_extract(response,'$.refs[0].teamId') ELSE NULL END),created_at,id) WHERE json_extract(response,'$.kind') IN ('cell-audit','format-audit');
CREATE INDEX sync_outbox_pending_idx ON sync_outbox(team_id,local_seq) WHERE status<>'acknowledged';
CREATE UNIQUE INDEX site_maintenance_active_idx ON site_maintenance_jobs(team_id) WHERE phase NOT IN ('complete','cancelled');
CREATE INDEX site_events_team_idx ON site_events(team_id,cursor);
CREATE INDEX sync_outbox_team_sequence ON sync_outbox(team_id,local_seq);
CREATE INDEX access_tokens_user_idx ON access_tokens(user_id,created_at);
PRAGMA writable_schema=OFF;
